using UnityEngine; #if ENABLE_INPUT_SYSTEM using UnityEngine.InputSystem; using UnityEngine.InputSystem.XR; using UnityEngine.InputSystem.Controls; #endif namespace DroneDigitalTwin.Virtual { [RequireComponent(typeof(Rigidbody))] public class VirtualDroneController : MonoBehaviour { // ============================================================ // DIGITAL TWIN // ============================================================ [Header("Digital Twin Link")] public DroneClient droneClient; // ============================================================ // FLIGHT SETTINGS // ============================================================ [Header("Flight Speeds")] public float maxHorizontalSpeed = 3f; public float maxVerticalSpeed = 2f; public float maxYawSpeed = 90f; // ============================================================ // PHYSICS // ============================================================ [Header("Physics Feel")] public float acceleration = 3f; public float brakingForce = 5f; // ============================================================ // VISUAL MODEL // ============================================================ [Header("Drone Visual")] public Transform droneVisualModel; public float maxVisualTilt = 20f; public float visualTiltSpeed = 8f; // ============================================================ // PROPELLERS // ============================================================ [Header("Propellers")] public Transform propellerFL; public Transform propellerFR; public Transform propellerBL; public Transform propellerBR; public float basePropellerSpeed = 1500f; public float movementPropellerBoost = 1000f; public float propellerAcceleration = 8f; private float currentPropellerSpeed; // ============================================================ // FLIGHT STATE // ============================================================ public bool isFlying { get; private set; } // ============================================================ // INPUT // ============================================================ public Vector2 LeftStickInput => leftStickInput; public Vector2 RightStickInput => rightStickInput; private Vector2 leftStickInput; private Vector2 rightStickInput; // ============================================================ // EVENTS // ============================================================ [Header("Events")] public UnityEngine.Events.UnityEvent onEmergencyLand; // ============================================================ // INTERNAL // ============================================================ private Rigidbody rb; private float rcSendTimer; private float rcSendInterval = 0.05f; // ============================================================ // START // ============================================================ private void Start() { rb = GetComponent<Rigidbody>(); rb.useGravity = true; // Compatible with older Unity Rigidbody API rb.drag = 0f; rb.angularDrag = 0f; // Prevent physical flipping. // Y rotation remains free. rb.constraints = RigidbodyConstraints.FreezeRotationX | RigidbodyConstraints.FreezeRotationZ; currentPropellerSpeed = 0f; if (droneVisualModel == null) { Debug.LogWarning( "[VirtualDrone] Drone Visual Model is not assigned." ); } } // ============================================================ // UPDATE // ============================================================ private void Update() { ReadInput(); HandleVisualTilting(); HandlePropellers(); SendRCCommandsToRealDrone(); } // ============================================================ // FIXED UPDATE // ============================================================ private void FixedUpdate() { if (isFlying) { ApplyTelloFlightMechanics(); } } // ============================================================ // TAKEOFF // ============================================================ public void Takeoff() { if (isFlying) return; isFlying = true; rb.useGravity = false; rb.velocity = new Vector3( 0f, 1.5f, 0f ); if (droneClient != null) { // Tello SDK command mode SendTelloCommand("command"); // Tello takeoff SendTelloCommand("takeoff"); } Debug.Log("[VirtualDrone] Takeoff Initiated."); } // ============================================================ // LAND // ============================================================ public void Land() { if (!isFlying) return; rb.velocity = new Vector3( 0f, -1f, 0f ); isFlying = false; rb.useGravity = true; if (droneClient != null) { SendTelloCommand("land"); } Debug.Log("[VirtualDrone] Landing Initiated."); } // ============================================================ // EMERGENCY LAND // ============================================================ public void EmergencyLand() { isFlying = false; rb.useGravity = true; rb.velocity = Vector3.zero; if (droneClient != null) { SendTelloCommand("emergency"); } onEmergencyLand?.Invoke(); Debug.LogWarning( "[VirtualDrone] EMERGENCY STOP!" ); } // ============================================================ // TELLO COMMAND // ============================================================ private void SendTelloCommand(string command) { if (droneClient == null) return; droneClient.SendCommand(command); Debug.Log( "[Tello] Command Sent: " + command ); } // ============================================================ // INPUT // ============================================================ private void ReadInput() { leftStickInput = Vector2.zero; rightStickInput = Vector2.zero; #if ENABLE_INPUT_SYSTEM // ======================================================== // LEFT VR CONTROLLER // ======================================================== if (XRController.leftHand != null) { var leftStick = XRController.leftHand["thumbstick"] as Vector2Control ?? XRController.leftHand["joystick"] as Vector2Control; if (leftStick != null) { leftStickInput = leftStick.ReadValue(); } } // ======================================================== // RIGHT VR CONTROLLER // ======================================================== if (XRController.rightHand != null) { var rightStick = XRController.rightHand["thumbstick"] as Vector2Control ?? XRController.rightHand["joystick"] as Vector2Control; if (rightStick != null) { rightStickInput = rightStick.ReadValue(); } // ---------------------------------------------------- // PRIMARY BUTTON = TAKEOFF // ---------------------------------------------------- var primaryBtn = XRController.rightHand["primaryButton"] as ButtonControl ?? XRController.rightHand["buttonA"] as ButtonControl; if (primaryBtn != null && primaryBtn.wasPressedThisFrame) { Takeoff(); } // ---------------------------------------------------- // SECONDARY BUTTON = LAND // ---------------------------------------------------- var secondaryBtn = XRController.rightHand["secondaryButton"] as ButtonControl ?? XRController.rightHand["buttonB"] as ButtonControl; if (secondaryBtn != null && secondaryBtn.wasPressedThisFrame) { Land(); } } // ======================================================== // BOTH TRIGGERS = EMERGENCY // ======================================================== if (XRController.leftHand != null && XRController.rightHand != null) { var leftTrigger = XRController.leftHand["trigger"] as ButtonControl; var rightTrigger = XRController.rightHand["trigger"] as ButtonControl; if (leftTrigger != null && rightTrigger != null && leftTrigger.isPressed && rightTrigger.isPressed) { EmergencyLand(); } } #if UNITY_EDITOR // ======================================================== // KEYBOARD FALLBACK // ======================================================== var keyboard = Keyboard.current; if (keyboard != null) { // T = Takeoff if (keyboard.tKey.wasPressedThisFrame) { Takeoff(); } // L = Land if (keyboard.lKey.wasPressedThisFrame) { Land(); } // ESC = Emergency if (keyboard.escapeKey.wasPressedThisFrame) { EmergencyLand(); } // ---------------------------------------------------- // KEYBOARD FLIGHT // ---------------------------------------------------- if (leftStickInput == Vector2.zero && rightStickInput == Vector2.zero && isFlying) { // PITCH float pitch = 0f; if (keyboard.wKey.isPressed) pitch = 1f; if (keyboard.sKey.isPressed) pitch = -1f; // ROLL float roll = 0f; if (keyboard.dKey.isPressed) roll = 1f; if (keyboard.aKey.isPressed) roll = -1f; // YAW float yaw = 0f; if (keyboard.rightArrowKey.isPressed) yaw = 1f; if (keyboard.leftArrowKey.isPressed) yaw = -1f; // THRUST float thrust = 0f; if (keyboard.upArrowKey.isPressed) thrust = 1f; if (keyboard.downArrowKey.isPressed) thrust = -1f; leftStickInput = new Vector2( roll, pitch ); rightStickInput = new Vector2( yaw, thrust ); } } #endif #endif } // ============================================================ // FLIGHT PHYSICS // ============================================================ private void ApplyTelloFlightMechanics() { float rollSpeed = leftStickInput.x * maxHorizontalSpeed; float pitchSpeed = leftStickInput.y * maxHorizontalSpeed; float thrustSpeed = rightStickInput.y * maxVerticalSpeed; Vector3 targetVelocity = (transform.forward * pitchSpeed) + (transform.right * rollSpeed) + (transform.up * thrustSpeed); bool isBraking = leftStickInput == Vector2.zero && rightStickInput.y == 0f; float currentAcceleration = isBraking ? brakingForce : acceleration; rb.velocity = Vector3.Lerp( rb.velocity, targetVelocity, Time.fixedDeltaTime * currentAcceleration ); // YAW float yawAmount = rightStickInput.x * maxYawSpeed * Time.fixedDeltaTime; Quaternion yawRotation = Quaternion.Euler( 0f, yawAmount, 0f ); rb.MoveRotation( rb.rotation * yawRotation ); } // ============================================================ // VISUAL TILT // ============================================================ private void HandleVisualTilting() { if (droneVisualModel == null) return; if (!isFlying) { droneVisualModel.localRotation = Quaternion.Lerp( droneVisualModel.localRotation, Quaternion.identity, Time.deltaTime * visualTiltSpeed ); return; } Vector3 localVelocity = transform.InverseTransformDirection( rb.velocity ); float pitchTilt = 0f; float rollTilt = 0f; if (leftStickInput.sqrMagnitude > 0.01f) { pitchTilt = leftStickInput.y * maxVisualTilt; rollTilt = -leftStickInput.x * maxVisualTilt; } else { pitchTilt = -(localVelocity.z / Mathf.Max(maxHorizontalSpeed, 0.01f)) * maxVisualTilt * 1.5f; rollTilt = (localVelocity.x / Mathf.Max(maxHorizontalSpeed, 0.01f)) * maxVisualTilt * 1.5f; pitchTilt = Mathf.Clamp( pitchTilt, -maxVisualTilt, maxVisualTilt ); rollTilt = Mathf.Clamp( rollTilt, -maxVisualTilt, maxVisualTilt ); } Quaternion targetRotation = Quaternion.Euler( pitchTilt, 0f, rollTilt ); droneVisualModel.localRotation = Quaternion.Lerp( droneVisualModel.localRotation, targetRotation, Time.deltaTime * visualTiltSpeed ); } // ============================================================ // PROPELLER SYSTEM // ============================================================ private void HandlePropellers() { float targetSpeed = 0f; if (isFlying) { targetSpeed = basePropellerSpeed; float movementAmount = leftStickInput.magnitude; float thrustAmount = Mathf.Abs( rightStickInput.y ); float boost = Mathf.Clamp01( movementAmount + thrustAmount ) * movementPropellerBoost; targetSpeed += boost; } currentPropellerSpeed = Mathf.Lerp( currentPropellerSpeed, targetSpeed, Time.deltaTime * propellerAcceleration ); RotatePropellers(); } // ============================================================ // ROTATE PROPELLERS // ============================================================ private void RotatePropellers() { if (propellerFL == null || propellerFR == null || propellerBL == null || propellerBR == null) { return; } float rotationAmount = currentPropellerSpeed * Time.deltaTime; propellerFL.Rotate( Vector3.forward * -rotationAmount, Space.Self ); propellerFR.Rotate( Vector3.forward * rotationAmount, Space.Self ); propellerBL.Rotate( Vector3.forward * rotationAmount, Space.Self ); propellerBR.Rotate( Vector3.forward * -rotationAmount, Space.Self ); } // ============================================================ // REAL TELLO RC // ============================================================ private void SendRCCommandsToRealDrone() { if (droneClient == null || !isFlying) { return; } rcSendTimer += Time.deltaTime; if (rcSendTimer >= rcSendInterval) { rcSendTimer = 0f; int rcRoll = Mathf.RoundToInt( leftStickInput.x * 100f ); int rcPitch = Mathf.RoundToInt( leftStickInput.y * 100f ); int rcThrust = Mathf.RoundToInt( rightStickInput.y * 100f ); int rcYaw = Mathf.RoundToInt( rightStickInput.x * 100f ); string rcCommand = $"rc {rcRoll} {rcPitch} {rcThrust} {rcYaw}"; droneClient.SendCommand( rcCommand ); } } } }